def extract(tree):
    rows = tree.where(content_desc="sourceLanguagePicker")
    if not rows:
        raise ValueError("Source language selector is absent")
    return rows[0]["name"] == "From language: English"

def extract(tree):
    rows = tree.where(content_desc="targetLanguagePicker")
    if not rows:
        raise ValueError("Destination language selector is absent")
    return rows[0]["name"] == "To language: Spanish"

def extract(tree):
    rows = tree.where(content_desc="languageStatusLabel")
    if not rows:
        raise ValueError("Language-pair status is absent")
    return "Needs download" in rows[0]["text"]

